/**
 * htnaPlotData — layout + render data for `plot_htna()` from htna 0.1.0.
 *
 * R `plot_htna()` is a 30+ option renderer that delegates layout + styling
 * to internal helpers and finally paints via cograph/igraph. tnaj owns
 * the *structural* layer here: given a TNA + a minimal set of options,
 * return a fully-typed render package that any consumer (demo, CarmNote,
 * Dynalytics, future svelte/react cells) can paint without recomputing
 * geometry.
 *
 * What's covered (matching plot_htna defaults):
 *   - Color palette: plot_htna's exact 12-color sequence
 *   - Shape palette: plot_htna's 8-shape sequence
 *   - Default per-actor color/shape: actorLevels[0] → palette[0], etc.
 *   - Layouts:
 *       'bipartite-arcs' (default, matches Dynalytics + tnaj demo norm)
 *       'circular'       (all nodes on one ring, R plot_htna fallback)
 *       'vertical'       (two columns, group1 left / group2 right)
 *       'horizontal'     (two rows)
 *   - Per-edge classification: 'within' / 'between' / 'self'
 *   - Edge color = source actor's color
 *
 * What's NOT covered (renderer responsibility):
 *   - Painting (SVG/canvas/base R graphics)
 *   - Self-loop control points, exact curvature shapes, arrowheads,
 *     label positioning, donut rings, legend boxes — those are visual
 *     decisions that each consumer makes consistently with its other
 *     plots. The structural data here is enough to drive any of them.
 */
import type { TNA } from '../core/types.js';
import { isHtna } from '../core/group.js';

/** plot_htna's default 12-color palette (exact hex codes). */
export const HTNA_COLOR_PALETTE = [
  '#4FC3F7', '#fbb550', '#7eb5d6', '#98d4a2',
  '#f4a582', '#92c5de', '#d6c1de', '#b8e186',
  '#fdcdac', '#cbd5e8', '#f4cae4', '#e6f5c9',
] as const;

/** plot_htna's default 8-shape palette. */
export const HTNA_SHAPE_PALETTE = [
  'circle', 'square', 'diamond', 'triangle',
  'pentagon', 'hexagon', 'star', 'cross',
] as const;

export type HtnaShape = (typeof HTNA_SHAPE_PALETTE)[number];

export type HtnaLayout = 'bipartite-arcs' | 'circular' | 'vertical' | 'horizontal';

export interface HtnaPlotOptions {
  layout?: HtnaLayout;
  width?: number;
  height?: number;
  /** Override per-actor color: actor name → hex. Default: HTNA_COLOR_PALETTE in actorLevels order. */
  groupColors?: Record<string, string>;
  /** Override per-actor shape: actor name → shape. Default: HTNA_SHAPE_PALETTE in actorLevels order. */
  groupShapes?: Record<string, HtnaShape>;
  /** Hide edges with weight strictly below this threshold. Default: 0 (show all non-zero). */
  edgeThreshold?: number;
  /** Curvature magnitude for within-group edges (0..1). Default 0.4 (matches R plot_htna). */
  curvature?: number;
  /** Bipartite-arcs only: half the horizontal distance between the two arc centers. Default 40. */
  bipartiteGapHalf?: number;
  /** Bipartite-arcs only: arc radius. Defaults to keep nodes inside the canvas. */
  bipartiteRadius?: number;
  /** Bipartite-arcs only: half-angle each side of the equator. Default 0.45π (≈81°). */
  bipartiteArcSpan?: number;
}

export interface HtnaPlotNode {
  id: string;
  label: string;
  partition: string;
  x: number;
  y: number;
  shape: HtnaShape;
  color: string;
  /** Initial-state probability (0..1) — drives the donut ring fill in renderers that show it. */
  initProb: number;
}

export interface HtnaPlotEdge {
  from: string;
  to: string;
  weight: number;
  /** Edge color = source actor's color. */
  color: string;
  /**
   * within  — both endpoints in the same actor group
   * between — endpoints in different actor groups
   * self    — self-loop (from === to)
   */
  kind: 'within' | 'between' | 'self';
  /**
   * Suggested curve magnitude as a unit-less fraction of chord length.
   * 0 means straight line. Renderer chooses sign (which side of the chord
   * the curve bows toward) based on its own conventions. For 'within' and
   * 'between' bidirectional pairs, renderer should pick opposite signs
   * for the two directions to disambiguate them.
   */
  curvature: number;
}

export interface HtnaPlotLegendEntry {
  name: string;
  color: string;
  shape: HtnaShape;
}

export interface HtnaPlotData {
  layout: HtnaLayout;
  width: number;
  height: number;
  nodes: HtnaPlotNode[];
  edges: HtnaPlotEdge[];
  legend: HtnaPlotLegendEntry[];
}

export function htnaPlotData(model: TNA, options: HtnaPlotOptions = {}): HtnaPlotData {
  if (!isHtna(model)) {
    throw new Error('htnaPlotData(): input must be an HTNA model (partition required).');
  }

  const {
    layout = 'bipartite-arcs',
    width = 1080,
    height = 840,
    edgeThreshold = 0,
    curvature = 0.4,
    bipartiteGapHalf = 40,
    bipartiteArcSpan = Math.PI * 0.45,
  } = options;

  const actorLevels = model.actorLevels ?? [...new Set(model.partition!)];

  // ── Resolve per-actor color + shape (using R defaults, overridable) ─
  const groupColors: Record<string, string> = {};
  const groupShapes: Record<string, HtnaShape> = {};
  for (let i = 0; i < actorLevels.length; i++) {
    const a = actorLevels[i]!;
    groupColors[a] = options.groupColors?.[a]
      ?? HTNA_COLOR_PALETTE[i % HTNA_COLOR_PALETTE.length]!;
    groupShapes[a] = options.groupShapes?.[a]
      ?? HTNA_SHAPE_PALETTE[i % HTNA_SHAPE_PALETTE.length]!;
  }

  // ── Compute node positions ──────────────────────────────────────────
  const positions = computePositions(
    model.labels,
    model.partition!,
    actorLevels,
    layout,
    width,
    height,
    { gapHalf: bipartiteGapHalf, arcSpan: bipartiteArcSpan, radius: options.bipartiteRadius },
  );

  const nodes: HtnaPlotNode[] = model.labels.map((label, i) => ({
    id: label,
    label,
    partition: model.partition![i]!,
    x: positions[i]!.x,
    y: positions[i]!.y,
    shape: groupShapes[model.partition![i]!]!,
    color: groupColors[model.partition![i]!]!,
    initProb: model.inits[i] ?? 0,
  }));

  // ── Build edge list ─────────────────────────────────────────────────
  const edges: HtnaPlotEdge[] = [];
  const n = model.labels.length;
  for (let i = 0; i < n; i++) {
    const srcActor = model.partition![i]!;
    for (let j = 0; j < n; j++) {
      const w = model.weights.get(i, j);
      if (w <= edgeThreshold) continue;
      const tgtActor = model.partition![j]!;
      let kind: HtnaPlotEdge['kind'];
      if (i === j) kind = 'self';
      else if (srcActor === tgtActor) kind = 'within';
      else kind = 'between';

      edges.push({
        from: model.labels[i]!,
        to: model.labels[j]!,
        weight: w,
        color: groupColors[srcActor]!,
        kind,
        curvature: kind === 'within' ? curvature : (kind === 'between' ? 0 : 0),
      });
    }
  }

  // ── Legend ──────────────────────────────────────────────────────────
  const legend: HtnaPlotLegendEntry[] = actorLevels.map(a => ({
    name: a,
    color: groupColors[a]!,
    shape: groupShapes[a]!,
  }));

  return { layout, width, height, nodes, edges, legend };
}

// ────────────────────────────────────────────────────────────────────
//  Layout computation
// ────────────────────────────────────────────────────────────────────

interface NodePos { x: number; y: number }

function computePositions(
  labels: string[],
  partition: string[],
  actorLevels: string[],
  layout: HtnaLayout,
  width: number,
  height: number,
  bipartite: { gapHalf: number; arcSpan: number; radius?: number },
): NodePos[] {
  const n = labels.length;
  const cx = width / 2;
  const cy = height / 2;

  if (layout === 'circular') {
    // Single ring, all nodes evenly spaced clockwise starting at top.
    const r = Math.min(cx, cy) * 0.7;
    return labels.map((_, i) => {
      const angle = -Math.PI / 2 + (2 * Math.PI * i) / n;
      return { x: cx + r * Math.cos(angle), y: cy + r * Math.sin(angle) };
    });
  }

  if (layout === 'vertical' || layout === 'horizontal') {
    // Two columns (vertical) or two rows (horizontal). Nodes in each group
    // are stacked in label order along the long axis.
    const groupA = actorLevels[0]!;
    const idxsA: number[] = [], idxsB: number[] = [];
    for (let i = 0; i < n; i++) {
      (partition[i] === groupA ? idxsA : idxsB).push(i);
    }
    const out: NodePos[] = new Array(n);
    if (layout === 'vertical') {
      const colA = cx - width * 0.25;
      const colB = cx + width * 0.25;
      const margin = height * 0.1;
      const innerH = height - 2 * margin;
      idxsA.forEach((idx, k) => {
        out[idx] = { x: colA, y: margin + (k + 0.5) * (innerH / Math.max(1, idxsA.length)) };
      });
      idxsB.forEach((idx, k) => {
        out[idx] = { x: colB, y: margin + (k + 0.5) * (innerH / Math.max(1, idxsB.length)) };
      });
    } else {
      const rowA = cy - height * 0.25;
      const rowB = cy + height * 0.25;
      const margin = width * 0.1;
      const innerW = width - 2 * margin;
      idxsA.forEach((idx, k) => {
        out[idx] = { x: margin + (k + 0.5) * (innerW / Math.max(1, idxsA.length)), y: rowA };
      });
      idxsB.forEach((idx, k) => {
        out[idx] = { x: margin + (k + 0.5) * (innerW / Math.max(1, idxsB.length)), y: rowB };
      });
    }
    return out;
  }

  // Default: 'bipartite-arcs'
  const groupA = actorLevels[0]!;
  const idxsA: number[] = [], idxsB: number[] = [];
  for (let i = 0; i < n; i++) {
    (partition[i] === groupA ? idxsA : idxsB).push(i);
  }
  const gapHalf = bipartite.gapHalf;
  const arcSpan = bipartite.arcSpan;
  const cxA = cx - gapHalf;
  const cxB = cx + gapHalf;
  // Default radius keeps the arcs inside the canvas
  const r = bipartite.radius
    ?? Math.min(cx - gapHalf - 60, (height - 100) / 2);

  const out: NodePos[] = new Array(n);
  // A arc on the LEFT: angles from (π + arcSpan) decreasing to (π − arcSpan)
  idxsA.forEach((idx, k) => {
    const t = idxsA.length > 1 ? k / (idxsA.length - 1) : 0.5;
    const a = (Math.PI + arcSpan) - t * (2 * arcSpan);
    out[idx] = { x: cxA + r * Math.cos(a), y: cy + r * Math.sin(a) };
  });
  // B arc on the RIGHT: angles from -arcSpan increasing to +arcSpan
  idxsB.forEach((idx, k) => {
    const t = idxsB.length > 1 ? k / (idxsB.length - 1) : 0.5;
    const a = -arcSpan + t * (2 * arcSpan);
    out[idx] = { x: cxB + r * Math.cos(a), y: cy + r * Math.sin(a) };
  });
  return out;
}
