/**
 * MCML hierarchical network plot.
 *
 * The computation/renderer boundary follows Nestimate + cograph:
 * - callers may pass an already-computed MCML object;
 * - a plain TNA may be adapted with named clusters for plotting;
 * - `mode` controls automatic edge labels and never rewrites weights.
 *
 * The returned plot-data package follows the same renderer-neutral pattern as
 * `htnaPlotData()`. `plotMCML()` is the bundled SVG painter for consumers that
 * do not need to supply their own D3/canvas renderer.
 */
import { Matrix } from '../core/matrix.js';
import type { TNA } from '../core/types.js';
import {
  networkArrowPolygon,
  networkEdgeGeometry,
  networkSelfLoopGeometry,
} from '../core/networkDrawing.js';

export const MCML_COLOR_PALETTE = [
  '#E69F00', '#56B4E9', '#009E73', '#F0E442',
  '#0072B2', '#D55E00', '#CC79A7', '#999999',
] as const;

export type McmlMatrix = Matrix | number[][];
export type McmlClusters = Record<string, readonly string[]>;
export type McmlTheme = 'classic' | 'rich' | 'light';
export type McmlSummaryPie = 'inits' | 'self';
export type McmlEdgeColorBy = 'auto' | 'cluster' | 'sign';
export type McmlAggregation = 'sum' | 'mean' | 'max';
export type McmlNodeShape = 'circle' | 'square' | 'diamond' | 'triangle';

export interface McmlLayerLike {
  weights: McmlMatrix;
  inits?: ArrayLike<number> | null;
  labels: string[];
  data?: unknown;
}

/** Structural contract shared by Nestimate `mcml` and cograph `cluster_summary`. */
export interface McmlLike {
  macro: McmlLayerLike;
  clusters?: Record<string, McmlLayerLike> | null;
  cluster_members: McmlClusters;
  meta?: {
    directed?: boolean;
    n_nodes?: number;
    n_clusters?: number;
    [key: string]: unknown;
  };
  nodes_df?: unknown;
  [key: string]: unknown;
}

export interface McmlPlotOptions {
  /** Required only when plotting a plain TNA. */
  clusters?: McmlClusters;
  /** Block aggregation used only for the plain-TNA adapter. Default `sum`. */
  aggregation?: McmlAggregation;
  /** Like current cograph: controls automatic labels, not weight conversion. */
  mode?: 'weights' | 'tna';
  theme?: McmlTheme;
  width?: number;
  height?: number;
  minimum?: number;
  directed?: boolean;
  colors?: string[];
  summaryPie?: McmlSummaryPie;
  edgeColorBy?: McmlEdgeColorBy;
  edgePositiveColor?: string;
  edgeNegativeColor?: string;
  edgeLabels?: boolean;
  summaryEdgeLabels?: boolean;
  edgeLabelDigits?: number;
  showLabels?: boolean;
  summaryLabels?: boolean;
  legend?: boolean;
  title?: string;
  subtitle?: string;
  spacing?: number;
  shapeSize?: number;
  summarySize?: number;
  skewAngle?: number;
  topLayerScale?: [number, number];
  /** This is the active layer-gap control in current cograph. */
  interLayerGap?: number;
  nodeRadiusScale?: number;
  nodeSize?: number;
  nodeShape?: McmlNodeShape | McmlNodeShape[];
  nodeDonut?: boolean;
  nodeDonutInnerRatio?: number;
  summaryDonutInnerRatio?: number;
  curvedEdges?: boolean;
  summaryCurve?: number;
  summaryArrows?: boolean;
  betweenArrows?: boolean;
  edgeWidthRange?: [number, number];
  betweenEdgeWidthRange?: [number, number];
  summaryEdgeWidthRange?: [number, number];
  edgeAlpha?: number;
  betweenEdgeAlpha?: number;
  summaryEdgeAlpha?: number;
  interLayerAlpha?: number;
  shellAlpha?: number;
  shellBorderWidth?: number;
  /** Compatibility-only: current cograph computes this but positions by `interLayerGap`. */
  layerSpacing?: number | null;
  /** Compatibility-only: summary nodes remain circular pies/donuts. */
  clusterShape?: string;
  /** Compatibility-only: detail labels are positioned radially. */
  labelPosition?: number;
}

export interface McmlPlotNode {
  id: string;
  label: string;
  cluster: string;
  x: number;
  y: number;
  radius: number;
  color: string;
  shape: McmlNodeShape;
  selfProportion: number;
}

export interface McmlPlotShell {
  id: string;
  label: string;
  x: number;
  y: number;
  rx: number;
  ry: number;
  color: string;
}

export interface McmlSummaryNode extends McmlPlotShell {
  radius: number;
  proportion: number;
}

export type McmlPlotEdgeKind = 'within' | 'between' | 'summary' | 'inter-layer';

export interface McmlPlotEdge {
  id: string;
  from: string;
  to: string;
  fromX: number;
  fromY: number;
  toX: number;
  toY: number;
  weight: number;
  kind: McmlPlotEdgeKind;
  color: string;
  width: number;
  opacity: number;
  directed: boolean;
  label?: string;
  curvature: number;
  loopRotation?: number;
}

export interface McmlPlotLegendEntry { name: string; color: string }

export interface McmlPlotData {
  width: number;
  height: number;
  directed: boolean;
  theme: McmlTheme;
  nodeDonut: boolean;
  summaryDonut: boolean;
  nodeDonutInnerRatio: number;
  summaryDonutInnerRatio: number;
  title?: string;
  subtitle?: string;
  shells: McmlPlotShell[];
  detailNodes: McmlPlotNode[];
  summaryNodes: McmlSummaryNode[];
  withinEdges: McmlPlotEdge[];
  betweenEdges: McmlPlotEdge[];
  summaryEdges: McmlPlotEdge[];
  interLayerEdges: McmlPlotEdge[];
  legend: McmlPlotLegendEntry[];
  options: Pick<McmlPlotOptions, 'showLabels' | 'summaryLabels' | 'legend' | 'shellAlpha' | 'shellBorderWidth'>;
}

interface MatrixView {
  rows: number;
  cols: number;
  get(i: number, j: number): number;
}

interface PreparedMcml {
  macro: { labels: string[]; weights: MatrixView; inits: number[] };
  clusters: Record<string, { labels: string[]; weights: MatrixView; inits: number[] }>;
  members: McmlClusters;
  directed: boolean;
}

const clamp = (x: number, lo = 0, hi = 1): number => Math.max(lo, Math.min(hi, x));
const finite = (x: number): boolean => Number.isFinite(x);

function matrixView(value: McmlMatrix, name: string): MatrixView {
  if (value instanceof Matrix) {
    if (value.rows !== value.cols) throw new Error(`${name} must be square.`);
    for (const x of value.data) if (!finite(x)) throw new Error(`${name} must contain finite weights.`);
    return value;
  }
  if (!Array.isArray(value) || value.length === 0 || !value.every(row => Array.isArray(row))) {
    throw new Error(`${name} must be a Matrix or a non-empty numeric matrix.`);
  }
  const n = value.length;
  if (value.some(row => row.length !== n)) throw new Error(`${name} must be square.`);
  for (const row of value) for (const x of row) {
    if (typeof x !== 'number' || !finite(x)) throw new Error(`${name} must contain finite weights.`);
  }
  return { rows: n, cols: n, get: (i, j) => value[i]![j]! };
}

function arrayFrom(values: ArrayLike<number> | null | undefined, n: number): number[] {
  if (values == null) return new Array(n).fill(0);
  const out = Array.from(values);
  if (out.length !== n || out.some(x => !finite(x))) throw new Error('MCML inits must be finite and match layer labels.');
  return out;
}

function isMcmlLike(input: TNA | McmlLike): input is McmlLike {
  return typeof input === 'object' && input !== null && 'macro' in input && 'cluster_members' in input;
}

function normalizeMembers(members: McmlClusters, labels: readonly string[]): { names: string[]; indices: number[][] } {
  const names = Object.keys(members);
  if (names.length === 0) throw new Error('MCML clusters must contain at least one named cluster.');
  const labelIndex = new Map(labels.map((label, i) => [label, i]));
  const seen = new Set<string>();
  const indices = names.map(name => {
    const nodes = members[name];
    if (!nodes || nodes.length === 0) throw new Error(`MCML cluster "${name}" is empty.`);
    return nodes.map(node => {
      if (!labelIndex.has(node)) throw new Error(`MCML cluster "${name}" contains unknown node "${node}".`);
      if (seen.has(node)) throw new Error(`MCML node "${node}" belongs to more than one cluster.`);
      seen.add(node);
      return labelIndex.get(node)!;
    });
  });
  if (seen.size !== labels.length) {
    const missing = labels.filter(label => !seen.has(label));
    throw new Error(`MCML clusters do not assign: ${missing.join(', ')}.`);
  }
  return { names, indices };
}

function aggregate(values: number[], method: McmlAggregation): number {
  const nonzero = values.filter(x => x !== 0);
  if (nonzero.length === 0) return 0;
  if (method === 'mean') return nonzero.reduce((a, b) => a + b, 0) / nonzero.length;
  if (method === 'max') return Math.max(...nonzero);
  return nonzero.reduce((a, b) => a + b, 0);
}

function prepareTna(model: TNA, options: McmlPlotOptions): PreparedMcml {
  if (!options.clusters) throw new Error('plotMCML(): `clusters` is required when input is a TNA model.');
  if (model.weights.rows !== model.labels.length || model.weights.cols !== model.labels.length) {
    throw new Error('plotMCML(): TNA labels and weight dimensions do not match.');
  }
  const { names, indices } = normalizeMembers(options.clusters, model.labels);
  const method = options.aggregation ?? 'sum';
  const directed = options.directed ?? model.type !== 'co-occurrence';
  const weightAt = (i: number, j: number): number => directed
    ? model.weights.get(i, j)
    : (model.weights.get(i, j) + model.weights.get(j, i)) / 2;
  const macro = new Matrix(names.length, names.length);
  for (let i = 0; i < names.length; i++) for (let j = 0; j < names.length; j++) {
    const values: number[] = [];
    for (const a of indices[i]!) for (const b of indices[j]!) values.push(weightAt(a, b));
    macro.set(i, j, aggregate(values, method));
  }
  const clusters: PreparedMcml['clusters'] = {};
  for (let c = 0; c < names.length; c++) {
    const name = names[c]!;
    const idx = indices[c]!;
    const matrix = new Matrix(idx.length, idx.length);
    for (let i = 0; i < idx.length; i++) for (let j = 0; j < idx.length; j++) {
      matrix.set(i, j, weightAt(idx[i]!, idx[j]!));
    }
    const initTotal = idx.reduce((sum, i) => sum + (model.inits[i] ?? 0), 0);
    const inits = idx.map(i => initTotal > 0 ? (model.inits[i] ?? 0) / initTotal : 1 / idx.length);
    clusters[name] = { labels: idx.map(i => model.labels[i]!), weights: matrix, inits };
  }
  const macroInits = indices.map(idx => idx.reduce((sum, i) => sum + (model.inits[i] ?? 0), 0));
  const initSum = macroInits.reduce((a, b) => a + b, 0);
  return {
    macro: { labels: names, weights: macro, inits: initSum > 0 ? macroInits.map(x => x / initSum) : macroInits.map(() => 1 / names.length) },
    clusters,
    members: options.clusters,
    directed,
  };
}

function prepareExisting(input: McmlLike, options: McmlPlotOptions): PreparedMcml {
  const names = input.macro.labels;
  const macroWeights = matrixView(input.macro.weights, 'MCML macro weights');
  if (names.length !== macroWeights.rows) throw new Error('MCML macro labels and weights do not match.');
  const memberNames = Object.keys(input.cluster_members);
  if (memberNames.length !== names.length || names.some(name => !input.cluster_members[name])) {
    throw new Error('MCML macro labels must match cluster_members names.');
  }
  normalizeMembers(input.cluster_members, memberNames.flatMap(name => [...input.cluster_members[name]!]));
  const clusters: PreparedMcml['clusters'] = {};
  for (const name of names) {
    const layer = input.clusters?.[name];
    const labels = [...input.cluster_members[name]!];
    if (!layer) {
      clusters[name] = { labels, weights: new Matrix(labels.length, labels.length), inits: new Array(labels.length).fill(0) };
      continue;
    }
    const weights = matrixView(layer.weights, `MCML cluster "${name}" weights`);
    if (weights.rows !== labels.length || layer.labels.length !== labels.length || layer.labels.some((x, i) => x !== labels[i])) {
      throw new Error(`MCML cluster "${name}" labels, members, and weights must have identical order.`);
    }
    clusters[name] = { labels, weights, inits: arrayFrom(layer.inits, labels.length) };
  }
  return {
    macro: { labels: [...names], weights: macroWeights, inits: arrayFrom(input.macro.inits, names.length) },
    clusters,
    members: input.cluster_members,
    directed: options.directed ?? input.meta?.directed !== false,
  };
}

function edgeWidth(value: number, max: number, range: [number, number]): number {
  return range[0] + (range[1] - range[0]) * Math.abs(value) / Math.max(max, 1e-12);
}

function roundValue(value: number, digits: number): number {
  const factor = 10 ** digits;
  return Math.round((value + Number.EPSILON) * factor) / factor;
}

function formatWeight(value: number, digits: number): string | undefined {
  const rounded = roundValue(value, digits);
  if (rounded === 0) return undefined;
  return rounded.toFixed(digits).replace(/\.0+$/, '').replace(/(\.\d*?)0+$/, '$1').replace(/^(-?)0\./, '$1.');
}

function shellPoint(shell: McmlPlotShell, target: McmlPlotShell): [number, number] {
  const angle = Math.atan2((target.y - shell.y) / shell.ry, (target.x - shell.x) / shell.rx);
  return [shell.x + shell.rx * Math.cos(angle), shell.y + shell.ry * Math.sin(angle)];
}

/** Build renderer-neutral geometry and styling for an MCML hierarchy. */
export function mcmlPlotData(input: TNA | McmlLike, options: McmlPlotOptions = {}): McmlPlotData {
  const prepared = isMcmlLike(input) ? prepareExisting(input, options) : prepareTna(input, options);
  const {
    width = 960, height = 760, theme = 'classic', mode = 'weights', minimum = 0,
    summaryPie = 'inits', edgeColorBy = 'auto', edgePositiveColor = '#2E7D32', edgeNegativeColor = '#C62828',
    edgeLabelDigits = 2, spacing = 3, shapeSize = 1.2, summarySize = 4, skewAngle = 60,
    topLayerScale = [0.8, 0.25], interLayerGap = 0.6, nodeRadiusScale = 0.55, nodeSize = 2.4,
    edgeWidthRange = [0.3, 1.3], betweenEdgeWidthRange = [0.5, 2], summaryEdgeWidthRange = [0.5, 2],
    edgeAlpha = 0.35, betweenEdgeAlpha = 0.6, summaryEdgeAlpha = 0.7, interLayerAlpha = 0.5,
  } = options;
  if (width <= 0 || height <= 0) throw new Error('MCML plot width and height must be positive.');
  if (minimum < 0) throw new Error('MCML plot minimum must be non-negative.');
  const names = prepared.macro.labels;
  const k = names.length;
  const colors = names.map((_, i) => options.colors?.[i % (options.colors?.length || 1)] ?? MCML_COLOR_PALETTE[i % MCML_COLOR_PALETTE.length]!);
  const compress = Math.cos(clamp(skewAngle, 0, 90) * Math.PI / 180);
  const unit = Math.min(width, height) / 8.5;
  const baseX = width / 2;
  const baseY = height * 0.70;
  const angles = names.map((_, i) => Math.PI / 2 - i * 2 * Math.PI / k);
  const shellRx = shapeSize * unit;
  const shellRy = Math.max(10, shellRx * compress);
  const shells: McmlPlotShell[] = names.map((name, i) => ({
    id: name, label: name,
    x: baseX + spacing * unit * Math.cos(angles[i]!),
    y: baseY - spacing * unit * Math.sin(angles[i]!) * compress,
    rx: shellRx, ry: shellRy, color: colors[i]!,
  }));
  // Intentionally follows current cograph: interLayerGap positions the layer;
  // layerSpacing is accepted above for compatibility but is not used.
  const bottomTop = Math.min(...shells.map(shell => shell.y - shell.ry));
  // Leave a stable title/subtitle band above the macro network. This also
  // gives outward self-loops and their labels breathing room.
  const topBaseY = bottomTop - spacing * interLayerGap * unit + 42;
  // The macro layer uses the same compact node scale as tnaj's established
  // network drawing (22px at its default canvas), rather than cograph's base-R
  // plot-unit pie radius. The latter becomes enormous when mapped directly to
  // a responsive SVG canvas.
  const summaryRadius = Math.max(18, summarySize / 4 * 27);
  const topRx = spacing * topLayerScale[0] * unit;
  const topRy = spacing * topLayerScale[1] * unit;
  const rowTotals = names.map((_, i) => {
    let sum = 0;
    for (let j = 0; j < k; j++) sum += prepared.macro.weights.get(i, j);
    return sum;
  });
  const summaryNodes: McmlSummaryNode[] = names.map((name, i) => ({
    id: `summary:${name}`, label: name,
    x: baseX + topRx * Math.cos(angles[i]!),
    y: topBaseY - topRy * Math.sin(angles[i]!),
    rx: summaryRadius, ry: summaryRadius, radius: summaryRadius, color: colors[i]!,
    proportion: clamp(summaryPie === 'inits'
      ? prepared.macro.inits[i] ?? 0
      : rowTotals[i]! > 0 ? prepared.macro.weights.get(i, i) / rowTotals[i]! : 0),
  }));
  const shapeValues = Array.isArray(options.nodeShape) ? options.nodeShape : [options.nodeShape ?? 'circle'];
  const detailNodes: McmlPlotNode[] = [];
  for (let c = 0; c < k; c++) {
    const name = names[c]!;
    const shell = shells[c]!;
    const layer = prepared.clusters[name]!;
    const nodeOrbit = shellRx * nodeRadiusScale;
    for (let i = 0; i < layer.labels.length; i++) {
      const angle = layer.labels.length === 1 ? Math.PI / 2 : Math.PI / 2 - i * 2 * Math.PI / layer.labels.length;
      let total = 0;
      for (let j = 0; j < layer.labels.length; j++) total += layer.weights.get(i, j);
      detailNodes.push({
        id: layer.labels[i]!, label: layer.labels[i]!, cluster: name,
        x: shell.x + (layer.labels.length === 1 ? 0 : nodeOrbit * Math.cos(angle)),
        y: shell.y - (layer.labels.length === 1 ? 0 : nodeOrbit * Math.sin(angle) * compress),
        radius: nodeSize * 0.045 * unit,
        color: colors[c]!, shape: shapeValues[detailNodes.length % shapeValues.length]!,
        selfProportion: clamp(total > 0 ? layer.weights.get(i, i) / total : 0),
      });
    }
  }
  const nodeById = new Map(detailNodes.map(node => [node.id, node]));
  const hasNegative = (() => {
    for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) if (prepared.macro.weights.get(i, j) < 0) return true;
    for (const name of names) {
      const w = prepared.clusters[name]!.weights;
      for (let i = 0; i < w.rows; i++) for (let j = 0; j < w.cols; j++) if (w.get(i, j) < 0) return true;
    }
    return false;
  })();
  const signColors = edgeColorBy === 'sign' || (edgeColorBy === 'auto' && hasNegative);
  const colorFor = (value: number, clusterColor: string) => signColors ? (value < 0 ? edgeNegativeColor : edgePositiveColor) : clusterColor;
  let macroMax = 0, withinMax = 0;
  for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) macroMax = Math.max(macroMax, Math.abs(prepared.macro.weights.get(i, j)));
  for (const name of names) {
    const w = prepared.clusters[name]!.weights;
    for (let i = 0; i < w.rows; i++) for (let j = 0; j < w.cols; j++) withinMax = Math.max(withinMax, Math.abs(w.get(i, j)));
  }
  const edgeLabels = options.edgeLabels ?? mode === 'tna';
  const summaryEdgeLabels = options.summaryEdgeLabels ?? mode === 'tna';
  const visible = (weight: number): boolean => Math.abs(weight) > minimum && roundValue(weight, edgeLabelDigits) !== 0;
  const withinEdges: McmlPlotEdge[] = [];
  for (let c = 0; c < k; c++) {
    const name = names[c]!;
    const layer = prepared.clusters[name]!;
    for (let i = 0; i < layer.labels.length; i++) for (let j = 0; j < layer.labels.length; j++) {
      if (!prepared.directed && j < i) continue;
      const weight = layer.weights.get(i, j);
      if (!visible(weight)) continue;
      const from = nodeById.get(layer.labels[i]!)!, to = nodeById.get(layer.labels[j]!)!;
      withinEdges.push({
        id: `within:${name}:${i}:${j}`, from: from.id, to: to.id,
        fromX: from.x, fromY: from.y, toX: to.x, toY: to.y,
        weight, kind: 'within', color: colorFor(weight, colors[c]!),
        width: edgeWidth(weight, withinMax, edgeWidthRange) * 1.5,
        opacity: edgeAlpha, directed: prepared.directed,
        label: edgeLabels ? formatWeight(weight, edgeLabelDigits) : undefined,
        curvature: 0,
        loopRotation: i === j ? Math.atan2(from.y - shells[c]!.y, from.x - shells[c]!.x) : undefined,
      });
    }
  }
  const betweenEdges: McmlPlotEdge[] = [];
  const summaryEdges: McmlPlotEdge[] = [];
  for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) {
    if (!prepared.directed && j < i) continue;
    const weight = prepared.macro.weights.get(i, j);
    if (!visible(weight)) continue;
    const sourceSummary = summaryNodes[i]!, targetSummary = summaryNodes[j]!;
    const loopRotation = i === j
      ? Math.atan2(sourceSummary.y - summaryNodes.reduce((s, n) => s + n.y, 0) / k, sourceSummary.x - baseX)
      : undefined;
    summaryEdges.push({
      id: `summary:${i}:${j}`, from: names[i]!, to: names[j]!,
      fromX: sourceSummary.x, fromY: sourceSummary.y, toX: targetSummary.x, toY: targetSummary.y,
      weight, kind: 'summary', color: colorFor(weight, colors[i]!),
      width: edgeWidth(weight, macroMax, summaryEdgeWidthRange) * 1.5,
      opacity: summaryEdgeAlpha, directed: prepared.directed && options.summaryArrows !== false,
      label: summaryEdgeLabels ? formatWeight(weight, edgeLabelDigits) : undefined,
      curvature: (options.curvedEdges ?? theme !== 'classic')
        ? (options.summaryCurve ?? (prepared.directed ? 0.25 : 0))
        : 0,
      loopRotation,
    });
    if (i === j) continue;
    const [x1, y1] = shellPoint(shells[i]!, shells[j]!);
    const [x2, y2] = shellPoint(shells[j]!, shells[i]!);
    betweenEdges.push({
      id: `between:${i}:${j}`, from: names[i]!, to: names[j]!,
      fromX: x1, fromY: y1, toX: x2, toY: y2,
      weight, kind: 'between', color: colorFor(weight, colors[i]!),
      width: edgeWidth(weight, macroMax, betweenEdgeWidthRange) * 1.5,
      opacity: betweenEdgeAlpha, directed: prepared.directed && options.betweenArrows === true,
      curvature: 0,
    });
  }
  const interLayerEdges: McmlPlotEdge[] = detailNodes.map((node, i) => {
    const c = names.indexOf(node.cluster);
    const target = summaryNodes[c]!;
    return {
      id: `inter-layer:${i}`, from: node.id, to: node.cluster,
      fromX: node.x, fromY: node.y, toX: target.x, toY: target.y,
      weight: 0, kind: 'inter-layer', color: colors[c]!, width: 1,
      opacity: interLayerAlpha, directed: false, curvature: 0,
    };
  });
  const styled = theme !== 'classic';
  return {
    width, height, directed: prepared.directed, theme,
    nodeDonut: options.nodeDonut ?? styled,
    // Macro nodes are painted by the shared tnaj network renderer: a compact
    // solid node plus a thin probability ring, never a large donut.
    summaryDonut: false,
    nodeDonutInnerRatio: clamp(options.nodeDonutInnerRatio ?? 0.55, 0.05, 0.95),
    summaryDonutInnerRatio: clamp(options.summaryDonutInnerRatio ?? 0.6, 0.05, 0.95),
    title: options.title, subtitle: options.subtitle,
    shells, detailNodes, summaryNodes, withinEdges, betweenEdges, summaryEdges, interLayerEdges,
    legend: names.map((name, i) => ({ name, color: colors[i]! })),
    options: {
      showLabels: options.showLabels ?? true,
      summaryLabels: options.summaryLabels ?? true,
      legend: options.legend ?? true,
      shellAlpha: options.shellAlpha ?? (theme === 'light' ? 0.10 : 0.15),
      shellBorderWidth: options.shellBorderWidth ?? (theme === 'light' ? 0 : 0.75),
    },
  };
}

function esc(value: unknown): string {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function arcPath(cx: number, cy: number, inner: number, outer: number, proportion: number): string {
  const p = clamp(proportion);
  if (p <= 0) return '';
  if (p >= 0.999999) {
    return `M${cx} ${cy - outer}A${outer} ${outer} 0 1 1 ${cx - .001} ${cy - outer}`
      + (inner > 0 ? `L${cx - .001} ${cy - inner}A${inner} ${inner} 0 1 0 ${cx} ${cy - inner}Z` : `L${cx} ${cy}Z`);
  }
  const start = -Math.PI / 2, end = start + p * 2 * Math.PI;
  const ox1 = cx + outer * Math.cos(start), oy1 = cy + outer * Math.sin(start);
  const ox2 = cx + outer * Math.cos(end), oy2 = cy + outer * Math.sin(end);
  const large = p > .5 ? 1 : 0;
  if (inner <= 0) return `M${cx} ${cy}L${ox1} ${oy1}A${outer} ${outer} 0 ${large} 1 ${ox2} ${oy2}Z`;
  const ix2 = cx + inner * Math.cos(end), iy2 = cy + inner * Math.sin(end);
  const ix1 = cx + inner * Math.cos(start), iy1 = cy + inner * Math.sin(start);
  return `M${ox1} ${oy1}A${outer} ${outer} 0 ${large} 1 ${ox2} ${oy2}L${ix2} ${iy2}A${inner} ${inner} 0 ${large} 0 ${ix1} ${iy1}Z`;
}

function loopPath(x: number, y: number, nodeRadius: number, rotation: number): string {
  const r = nodeRadius * .8, d = nodeRadius;
  const cx = x + d * Math.cos(rotation), cy = y + d * Math.sin(rotation);
  const alpha = Math.acos(clamp((d * d + r * r - nodeRadius * nodeRadius) / (2 * d * r), -1, 1));
  const start = rotation + Math.PI + alpha, end = rotation + Math.PI - alpha + 2 * Math.PI;
  return `M${cx + r * Math.cos(start)} ${cy + r * Math.sin(start)}A${r} ${r} 0 1 1 ${cx + r * Math.cos(end)} ${cy + r * Math.sin(end)}`;
}

function edgePath(edge: McmlPlotEdge, radiusFrom = 0, radiusTo = 0): { path: string; lx: number; ly: number } {
  if (edge.from === edge.to || (edge.fromX === edge.toX && edge.fromY === edge.toY)) {
    const rotation = edge.loopRotation ?? -Math.PI / 2;
    const r = Math.max(radiusFrom, 8);
    return { path: loopPath(edge.fromX, edge.fromY, r, rotation), lx: edge.fromX + 2.3 * r * Math.cos(rotation), ly: edge.fromY + 2.3 * r * Math.sin(rotation) };
  }
  const dx = edge.toX - edge.fromX, dy = edge.toY - edge.fromY, len = Math.hypot(dx, dy) || 1;
  const ux = dx / len, uy = dy / len;
  const x1 = edge.fromX + ux * radiusFrom, y1 = edge.fromY + uy * radiusFrom;
  const x2 = edge.toX - ux * radiusTo, y2 = edge.toY - uy * radiusTo;
  const labelT = edge.directed ? .7 : .5;
  if (edge.curvature === 0) return {
    path: `M${x1} ${y1}L${x2} ${y2}`,
    lx: x1 + (x2 - x1) * labelT,
    ly: y1 + (y2 - y1) * labelT,
  };
  const px = -uy, py = ux, bend = len * edge.curvature;
  const cx = (x1 + x2) / 2 + px * bend, cy = (y1 + y2) / 2 + py * bend;
  return {
    path: `M${x1} ${y1}Q${cx} ${cy} ${x2} ${y2}`,
    lx: (1 - labelT) ** 2 * x1 + 2 * (1 - labelT) * labelT * cx + labelT ** 2 * x2,
    ly: (1 - labelT) ** 2 * y1 + 2 * (1 - labelT) * labelT * cy + labelT ** 2 * y2,
  };
}

let svgId = 0;

/** Render an MCML hierarchy as a self-contained SVG string. */
export function plotMCML(input: TNA | McmlLike, options: McmlPlotOptions = {}): string {
  const data = mcmlPlotData(input, options);
  const marker = `mcml-arrow-${++svgId}`;
  const nodeById = new Map(data.detailNodes.map(node => [node.id, node]));
  const summaryById = new Map(data.summaryNodes.map(node => [node.label, node]));
  let body = `<defs><marker id="${marker}" viewBox="0 0 7 6" refX="6.4" refY="3" markerWidth="5" markerHeight="4.3" orient="auto" markerUnits="userSpaceOnUse"><path d="M0 0L7 3L0 6Z" fill="context-stroke"/></marker></defs>`;
  const renderEdge = (edge: McmlPlotEdge, radiusFrom = 0, radiusTo = 0, dash = false): string => {
    const geometry = edgePath(edge, radiusFrom, radiusTo);
    return `<path class="mcml-edge mcml-edge-${edge.kind}" data-from="${esc(edge.from)}" data-to="${esc(edge.to)}" data-weight="${edge.weight}" d="${geometry.path}" fill="none" stroke="${esc(edge.color)}" stroke-width="${edge.width}" stroke-opacity="${edge.opacity}" stroke-linecap="round"${dash ? ' stroke-dasharray="6 5"' : ''}${edge.directed ? ` marker-end="url(#${marker})"` : ''}/>`
      + (edge.label ? `<text class="mcml-edge-label" data-from="${esc(edge.from)}" data-to="${esc(edge.to)}" x="${geometry.lx}" y="${geometry.ly - 4}" text-anchor="middle">${esc(edge.label)}</text>` : '');
  };
  // A cluster shell already communicates membership. Drawing one dashed guide
  // per detail node sends those guides through the cluster's own network and
  // can make them indistinguishable from real transitions. Collapse the
  // visual scaffolding to one summary-boundary → shell-boundary guide per
  // cluster while retaining the node-level mapping in mcmlPlotData().
  const interLayerGuides = data.shells.map(shell => {
    const summary = summaryById.get(shell.id)!;
    const dx = shell.x - summary.x, dy = shell.y - summary.y;
    const length = Math.hypot(dx, dy) || 1;
    const ux = dx / length, uy = dy / length;
    const sourceRadius = summary.radius + 6;
    const sourceX = summary.x + ux * sourceRadius;
    const sourceY = summary.y + uy * sourceRadius;
    const [targetX, targetY] = shellPoint(shell, {
      ...shell,
      x: summary.x,
      y: summary.y,
    });
    return `<path class="mcml-edge mcml-edge-inter-layer mcml-cluster-guide" data-cluster="${esc(shell.id)}" d="M${sourceX} ${sourceY}L${targetX} ${targetY}" fill="none" stroke="${esc(shell.color)}" stroke-width="1" stroke-opacity="${data.interLayerEdges.find(edge => edge.to === shell.id)?.opacity ?? .5}" stroke-dasharray="6 5"/>`;
  }).join('');
  body += `<g class="mcml-inter-layer">${interLayerGuides}</g>`;
  const summaryPairSet = new Set(data.summaryEdges
    .filter(edge => edge.from !== edge.to)
    .map(edge => `${edge.from}\u0000${edge.to}`));
  const summaryCenterX = data.summaryNodes.reduce((sum, node) => sum + node.x, 0) / data.summaryNodes.length;
  const summaryCenterY = data.summaryNodes.reduce((sum, node) => sum + node.y, 0) / data.summaryNodes.length;
  const renderSummaryEdge = (edge: McmlPlotEdge): string => {
    const from = summaryById.get(edge.from)!, to = summaryById.get(edge.to)!;
    const paintedRadius = from.radius + 6;
    const geometry = edge.from === edge.to
      ? networkSelfLoopGeometry(
        from.x, from.y, paintedRadius,
        Math.atan2(from.y - summaryCenterY, from.x - summaryCenterX),
      )
      : networkEdgeGeometry(
        from.x, from.y, to.x, to.y, paintedRadius, to.radius + 6,
        summaryPairSet.has(`${edge.to}\u0000${edge.from}`)
          ? Math.min(22, Math.hypot(to.x - from.x, to.y - from.y) * .14)
          : 0,
      );
    if (!geometry.path) return '';
    const labelY = geometry.labelY + (edge.from === edge.to ? 3 : -4);
    return `<path class="mcml-edge mcml-edge-summary" data-from="${esc(edge.from)}" data-to="${esc(edge.to)}" data-weight="${edge.weight}" d="${geometry.path}" fill="none" stroke="${esc(edge.color)}" stroke-width="${edge.width}" stroke-opacity="${edge.opacity}" stroke-linecap="round"/>`
      + (edge.directed
        ? `<polygon class="mcml-summary-arrow" points="${networkArrowPolygon(geometry.tipX, geometry.tipY, geometry.tipDx, geometry.tipDy)}" fill="${esc(edge.color)}" fill-opacity="${Math.min(1, edge.opacity + .18)}"/>`
        : '')
      + (edge.label
        ? `<text class="mcml-edge-label" x="${geometry.labelX}" y="${labelY}" text-anchor="middle">${esc(edge.label)}</text>`
        : '');
  };
  body += '<g class="mcml-summary-edges">' + data.summaryEdges.map(renderSummaryEdge).join('') + '</g>';
  body += '<g class="mcml-between-edges">' + data.betweenEdges.map(edge => renderEdge(edge)).join('') + '</g>';
  body += '<g class="mcml-shells">' + data.shells.map(shell => `<ellipse class="mcml-shell" data-cluster="${esc(shell.id)}" cx="${shell.x}" cy="${shell.y}" rx="${shell.rx}" ry="${shell.ry}" fill="${esc(shell.color)}" fill-opacity="${data.options.shellAlpha}" stroke="${esc(shell.color)}" stroke-width="${data.options.shellBorderWidth}"/>`).join('') + '</g>';
  const withinByDirection = new Map(data.withinEdges.map(edge => [`${edge.from}\u0000${edge.to}`, edge]));
  const renderedWithinPairs = new Set<string>();
  const renderReciprocalWithin = (forward: McmlPlotEdge, reverse: McmlPlotEdge): string => {
    const source = nodeById.get(forward.from)!, target = nodeById.get(forward.to)!;
    const dx = target.x - source.x, dy = target.y - source.y, length = Math.hypot(dx, dy) || 1;
    const ux = dx / length, uy = dy / length;
    const sourceX = source.x + ux * source.radius, sourceY = source.y + uy * source.radius;
    const targetX = target.x - ux * target.radius, targetY = target.y - uy * target.radius;
    const midX = (sourceX + targetX) / 2, midY = (sourceY + targetY) / 2;
    // Each half retains its direction's width/color. Together they read as
    // one chord with an arrow at each node end.
    const half = (edge: McmlPlotEdge, endX: number, endY: number): string => {
      const labelX = midX + (endX - midX) * .42;
      const labelY = midY + (endY - midY) * .42 - 4;
      return `<path class="mcml-edge mcml-edge-within mcml-edge-reciprocal-half" data-from="${esc(edge.from)}" data-to="${esc(edge.to)}" data-weight="${edge.weight}" d="M${midX} ${midY}L${endX} ${endY}" fill="none" stroke="${esc(edge.color)}" stroke-width="${edge.width}" stroke-opacity="${edge.opacity}" stroke-linecap="round" marker-end="url(#${marker})"/>`
        + (edge.label ? `<text class="mcml-edge-label" data-from="${esc(edge.from)}" data-to="${esc(edge.to)}" x="${labelX}" y="${labelY}" text-anchor="middle">${esc(edge.label)}</text>` : '');
    };
    return `<g class="mcml-reciprocal-edge" data-pair="${esc([forward.from, forward.to].sort().join('↔'))}">`
      + half(forward, targetX, targetY)
      + half(reverse, sourceX, sourceY)
      + '</g>';
  };
  let withinBody = '';
  for (const edge of data.withinEdges) {
    const pairKey = edge.from < edge.to ? `${edge.from}\u0000${edge.to}` : `${edge.to}\u0000${edge.from}`;
    const reverse = edge.from !== edge.to ? withinByDirection.get(`${edge.to}\u0000${edge.from}`) : undefined;
    if (edge.directed && reverse) {
      if (renderedWithinPairs.has(pairKey)) continue;
      renderedWithinPairs.add(pairKey);
      withinBody += renderReciprocalWithin(edge, reverse);
    } else {
      const from = nodeById.get(edge.from)!, to = nodeById.get(edge.to)!;
      withinBody += renderEdge(edge, from.radius, to.radius);
    }
  }
  body += `<g class="mcml-within-edges">${withinBody}</g>`;
  const renderPie = (x: number, y: number, r: number, p: number, color: string, donut: boolean, innerRatio: number, bg: string, cls: string) => {
    const inner = donut ? r * innerRatio : 0;
    return `<g class="${cls}"><circle cx="${x}" cy="${y}" r="${r}" fill="${esc(bg)}" stroke="#555" stroke-width="1"/>`
      + (p > 0 ? `<path d="${arcPath(x, y, inner, r, p)}" fill="${esc(color)}"/>` : '')
      + (donut ? `<circle cx="${x}" cy="${y}" r="${inner}" fill="#fff"/>` : '')
      + `<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="#555" stroke-width="1"/></g>`;
  };
  body += '<g class="mcml-detail-nodes">';
  for (const node of data.detailNodes) {
    if (node.shape === 'circle') body += renderPie(node.x, node.y, node.radius, node.selfProportion, node.color, data.nodeDonut, data.nodeDonutInnerRatio, '#e5e7eb', 'mcml-detail-node');
    else if (node.shape === 'square') body += `<rect class="mcml-detail-node" x="${node.x - node.radius}" y="${node.y - node.radius}" width="${2 * node.radius}" height="${2 * node.radius}" fill="${esc(node.color)}" stroke="#555"/>`;
    else if (node.shape === 'diamond') body += `<path class="mcml-detail-node" d="M${node.x} ${node.y - node.radius}L${node.x + node.radius} ${node.y}L${node.x} ${node.y + node.radius}L${node.x - node.radius} ${node.y}Z" fill="${esc(node.color)}" stroke="#555"/>`;
    else body += `<path class="mcml-detail-node" d="M${node.x} ${node.y - node.radius}L${node.x + node.radius} ${node.y + node.radius}L${node.x - node.radius} ${node.y + node.radius}Z" fill="${esc(node.color)}" stroke="#555"/>`;
    if (data.options.showLabels) {
      const shell = data.shells.find(x => x.id === node.cluster)!;
      const side = node.x >= shell.x ? 1 : -1;
      body += `<text class="mcml-node-label" x="${node.x + side * (node.radius + 5)}" y="${node.y + 4}" text-anchor="${side > 0 ? 'start' : 'end'}">${esc(node.label)}</text>`;
    }
  }
  body += '</g><g class="mcml-summary-nodes">';
  for (const node of data.summaryNodes) {
    const ringInner = node.radius + 2;
    const ringOuter = node.radius + 6;
    body += `<g class="mcml-summary-node" data-cluster="${esc(node.label)}">`
      + `<circle cx="${node.x}" cy="${node.y}" r="${ringOuter}" fill="#e5e7eb"/>`
      + (node.proportion > 0
        ? `<path d="${arcPath(node.x, node.y, ringInner, ringOuter, node.proportion)}" fill="${esc(node.color)}"/>`
        : '')
      + `<circle cx="${node.x}" cy="${node.y}" r="${node.radius}" fill="${esc(node.color)}" stroke="#777" stroke-width="1.5"/>`;
    if (data.options.summaryLabels) {
      body += `<text class="mcml-summary-label mcml-summary-label-inside" x="${node.x}" y="${node.y + 3.5}" text-anchor="middle">${esc(node.label)}</text>`;
    }
    body += '</g>';
  }
  body += '</g>';
  if (data.options.legend) {
    const lx = data.width - 145, ly = data.height - 28 - data.legend.length * 22;
    body += `<g class="mcml-legend" transform="translate(${lx} ${ly})"><text class="mcml-legend-title" font-weight="700">Clusters</text>`;
    data.legend.forEach((entry, i) => { body += `<circle cx="8" cy="${22 + i * 22}" r="7" fill="${esc(entry.color)}"/><text x="22" y="${26 + i * 22}">${esc(entry.name)}</text>`; });
    body += '</g>';
  }
  if (data.title) body += `<text class="mcml-title" x="${data.width / 2}" y="25" text-anchor="middle">${esc(data.title)}</text>`;
  if (data.subtitle) body += `<text class="mcml-subtitle" x="${data.width / 2}" y="45" text-anchor="middle">${esc(data.subtitle)}</text>`;
  const label = data.title ?? 'Multi-cluster multi-layer network';
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${data.width} ${data.height}" width="${data.width}" height="${data.height}" role="img" aria-label="${esc(label)}"><style>
    .mcml-title{font:700 18px system-ui,sans-serif}.mcml-subtitle{font:12px system-ui,sans-serif;fill:#666}
    .mcml-node-label,.mcml-summary-label,.mcml-edge-label,.mcml-legend text{font:11px system-ui,sans-serif;fill:#333;paint-order:stroke;stroke:#fff;stroke-width:3px;stroke-linejoin:round}.mcml-summary-label{font-weight:650}.mcml-summary-label-inside{font-size:10px;stroke-width:2.5px}.mcml-edge-label{font-size:10px}.mcml-legend-title{font:700 11px system-ui,sans-serif;fill:#555}
  </style>${body}</svg>`;
}

/** R-style aliases. */
export const plot_mcml = plotMCML;
export const mcml_plot_data = mcmlPlotData;
