/**
 * sequencePlotHtnaData — Data layer for `sequence_plot_htna()` from htna 0.1.0.
 *
 * R `sequence_plot_htna()` is two thin layers stacked:
 *   1. A pure data transform over the HTNA model's session data.
 *   2. A delegation to `Nestimate::sequence_plot()` for rendering.
 *
 * tnaj owns (1) here; (2) lives in whichever consumer renders the
 * matrix (Dynalytics' sequence ribbons, CarmNote cells, demo, etc.).
 *
 * Two modes:
 *
 *   by = 'group' (re-encode by actor type)
 *     Every cell of the session matrix is replaced by its actor-type
 *     label. Result is one matrix [sessions × maxLen] of actor strings
 *     (e.g. "Human" / "AI") with `null` for missing cells.
 *
 *   by = 'state' (default — split per actor, then stack)
 *     For each actor, filter each session to only that actor's events
 *     and pack into a per-actor matrix (right-padded with null).
 *     Then stack all per-actor matrices into one wide matrix; the
 *     parallel `group: string[]` tags each row with its source actor.
 */
import type { TNA } from '../core/types.js';
import { isHtna } from '../core/group.js';

export interface SequencePlotHtnaOptions {
  /**
   * 'state' (default): split sessions per actor, stack → renderer plots
   *                    one sequence-per-actor-per-session row.
   * 'group':           re-encode each event as its actor type, producing
   *                    one row per original session with actor-type cells.
   */
  by?: 'state' | 'group';
  /**
   * Canonical actor ordering (overrides `model.actorLevels`). Determines
   * the per-actor split order in 'state' mode.
   */
  actorLevels?: string[];
}

export interface SequencePlotHtnaData {
  by: 'state' | 'group';
  /** Actor labels in canonical order. */
  actors: string[];
  /** Wide-format session matrix (rows = sessions, cols = positions). */
  data: (string | null)[][];
  /** Per-row actor tag (length = data.length). Same value repeated for 'group' mode. */
  group: string[];
  /**
   * Per-actor session-matrix pieces (only populated for `by = 'state'`).
   * Keyed by actor name; same row-count semantics as `data` but split
   * apart so consumers can render per-actor heatmaps/indices side by side.
   */
  pieces?: Record<string, (string | null)[][]>;
}

export function sequencePlotHtnaData(
  model: TNA,
  options: SequencePlotHtnaOptions = {},
): SequencePlotHtnaData {
  if (!isHtna(model)) {
    throw new Error('sequencePlotHtnaData(): input must be an HTNA model (partition required).');
  }
  if (!model.data || model.data.length === 0) {
    throw new Error('sequencePlotHtnaData(): model has no sequence data.');
  }
  const { by = 'state' } = options;

  // type_map: code → actor
  const typeMap = new Map<string, string>();
  for (let i = 0; i < model.labels.length; i++) {
    typeMap.set(model.labels[i]!, model.partition![i]!);
  }

  // Canonical actor order. R uses sort(unique(node_groups$group)); we
  // honour an explicit override, otherwise sorted-unique to match R.
  const actors = options.actorLevels
    ? [...options.actorLevels]
    : [...new Set(model.partition!)].sort();

  if (by === 'group') {
    // Re-encode every cell as its actor type
    const maxLen = model.data.reduce((m, s) => Math.max(m, s.length), 0);
    const data: (string | null)[][] = model.data.map(session => {
      const row: (string | null)[] = new Array(maxLen).fill(null);
      for (let j = 0; j < session.length; j++) {
        const code = session[j];
        if (code === null || code === undefined || code === '') continue;
        const actor = typeMap.get(code);
        row[j] = actor ?? null;
      }
      return row;
    });
    // R's by='group' returns ONE row per original session, all sharing
    // "by='group'" semantics — there's no actor tag because every row
    // mixes actor types. Group vector left empty for consistency.
    return { by: 'group', actors, data, group: [] };
  }

  // by = 'state': per-actor split + stack
  const pieces: Record<string, (string | null)[][]> = {};
  for (const a of actors) pieces[a] = [];

  for (const session of model.data) {
    // Group session events by actor, preserving order, dropping nulls
    const perActor: Record<string, string[]> = {};
    for (const a of actors) perActor[a] = [];
    for (const code of session) {
      if (code === null || code === undefined || code === '') continue;
      const a = typeMap.get(code);
      if (a !== undefined && perActor[a] !== undefined) perActor[a]!.push(code);
    }
    for (const a of actors) {
      if (perActor[a]!.length > 0) {
        pieces[a]!.push(perActor[a]!);
      }
    }
  }

  // Compute max length per actor (then global max to align all pieces)
  const perActorMaxLen: Record<string, number> = {};
  for (const a of actors) {
    perActorMaxLen[a] = pieces[a]!.reduce((m, r) => Math.max(m, r.length), 0);
  }
  const globalMaxLen = Math.max(0, ...Object.values(perActorMaxLen));

  // Right-pad every row to globalMaxLen with null
  const paddedPieces: Record<string, (string | null)[][]> = {};
  for (const a of actors) {
    paddedPieces[a] = pieces[a]!.map(row => {
      if (row.length >= globalMaxLen) return [...row];
      const padded: (string | null)[] = [...row];
      while (padded.length < globalMaxLen) padded.push(null);
      return padded;
    });
  }

  // Stack: concatenate all actors' rows + parallel group vector
  const data: (string | null)[][] = [];
  const group: string[] = [];
  for (const a of actors) {
    for (const row of paddedPieces[a]!) {
      data.push(row);
      group.push(a);
    }
  }

  return { by: 'state', actors, data, group, pieces: paddedPieces };
}
