/**
 * extractMetaPaths — Type-level meta-path enumeration over an HTNA.
 *
 * Port of R `extract_meta_paths()` from htna 0.1.0 (installed binary,
 * NOT the GitHub source — see memory `htna-binary-vs-source-divergence`).
 *
 * Concept: given a TNA whose nodes are partitioned by actor type
 * (e.g. Human / AI), each session is re-encoded as a sequence of actor
 * types. The function enumerates k-length patterns of actor types
 * (length 2..4 by default) that occur in the sessions, returning
 * count / support / frequency / lift per pattern.
 *
 * Lift is computed against the marginal-independence null:
 *     expected_count = prod(marg_p[type_j]) * total_windows
 *     lift           = count / expected_count
 * where marg_p is the per-type marginal frequency across all events.
 *
 * Schema filtering: `schema = "Human->AI->Human"` keeps only that one
 * pattern. `schema = "Human->*->Human"` keeps every k=3 pattern whose
 * first and last elements are Human. Schema parts may be type names
 * or `"*"` (wildcard) — concrete state names are NOT supported in the
 * installed v0.1.0 binary (they'd require state-level enumeration,
 * which the binary doesn't expose).
 *
 * Output rows are sorted by (length asc, gap asc, count desc) to match R.
 */
import type { TNA } from '../core/types.js';
import { isHtna } from '../core/group.js';

export interface MetaPathRow {
  /** Pattern, e.g. "Human->AI->Human". */
  schema: string;
  /** Number of elements in the pattern (k). */
  length: number;
  /** Gap between consecutive positions; 0 for contiguous patterns. */
  gap: number;
  /** Total occurrences across all sessions. */
  count: number;
  /** Number of distinct sessions containing the pattern at least once. */
  nSequences: number;
  /** Proportion of sessions containing the pattern (`nSequences / total_n_sessions`). */
  support: number;
  /** Relative frequency within (length, gap) group (`count / sum(count_at_same_length_gap)`). */
  frequency: number;
  /** Observed-over-expected ratio under marginal independence. NaN if expected is 0. */
  lift: number;
}

export interface ExtractMetaPathsOptions {
  /** Pattern lengths to enumerate. Default [2, 3, 4]. Ignored when `schema` is set. */
  length?: number[];
  /** Schema DSL: e.g. "Human->AI->Human", "Human->*->Human". Concrete states NOT supported. */
  schema?: string;
  /** "contiguous" (default): consecutive positions. "gapped": positions spaced by `gap + 1`. */
  type?: 'contiguous' | 'gapped';
  /** Gap size(s) for `type='gapped'`. Default [1]. Multiple values yield one row per (length, gap). */
  gap?: number | number[];
  /** Minimum count to retain a row. Default 1. */
  minCount?: number;
  /** Minimum support (proportion of sessions). Default 0. */
  minSupport?: number;
  /** Minimum lift; 0 disables the filter. Default 0. */
  minLift?: number;
  /** Keep only patterns whose first element is in this set. */
  start?: string[];
  /** Keep only patterns whose last element is in this set. */
  end?: string[];
  /** Keep only patterns containing every element in this set. */
  contain?: string[];
}

/**
 * Enumerate type-level meta-paths in an HTNA. See file docstring for details.
 */
export function extractMetaPaths(model: TNA, options: ExtractMetaPathsOptions = {}): MetaPathRow[] {
  if (!isHtna(model)) {
    throw new Error('extractMetaPaths(): input must be an HTNA model (partition required).');
  }
  if (!model.data || model.data.length === 0) {
    throw new Error('extractMetaPaths(): model has no sequence data (`model.data` is empty).');
  }

  const {
    length: lengths = [2, 3, 4],
    schema,
    type = 'contiguous',
    gap = 1,
    minCount = 1,
    minSupport = 0,
    minLift = 0,
    start,
    end,
    contain,
  } = options;

  // ── Build alphabet + per-node lookup ────────────────────────────────
  const alphabet = model.actorLevels ?? uniqueInOrder(model.partition!);
  const T = alphabet.length;
  const codeToActorIdx = new Map<string, number>();
  for (let i = 0; i < model.labels.length; i++) {
    const actor = model.partition![i]!;
    const aIdx = alphabet.indexOf(actor);
    if (aIdx < 0) {
      throw new Error(
        `extractMetaPaths(): partition tag "${actor}" not in actorLevels [${alphabet.join(', ')}].`,
      );
    }
    codeToActorIdx.set(model.labels[i]!, aIdx);
  }

  // ── Encode sessions: SequenceData → int_seqs (filter nulls/empty) ─
  const intSeqs: Int32Array[] = [];
  for (const session of model.data) {
    const buf: number[] = [];
    for (const code of session) {
      if (code === null || code === undefined || code === '') continue;
      const aIdx = codeToActorIdx.get(code);
      if (aIdx === undefined) continue; // unknown code — silently skipped, matches R
      buf.push(aIdx);
    }
    intSeqs.push(Int32Array.from(buf));
  }
  const nSeq = intSeqs.length;

  // ── Marginal frequency per type ─────────────────────────────────────
  const margP = marginalFreq(intSeqs, T);

  // ── Determine gap_vals ──────────────────────────────────────────────
  let gapVals: number[];
  if (type === 'contiguous') {
    gapVals = [0];
  } else {
    const gArr = Array.isArray(gap) ? gap : [gap];
    if (gArr.length === 0 || gArr.some(g => !Number.isInteger(g) || g < 0)) {
      throw new Error('extractMetaPaths(): `gap` must be one or more non-negative integers.');
    }
    gapVals = [...new Set(gArr)].sort((a, b) => a - b);
    // R behaviour: contiguous-equivalent gap=0 falls back to 1 when type='gapped'
    if (gapVals.length === 1 && gapVals[0] === 0) gapVals = [1];
  }

  // ── Validate length ─────────────────────────────────────────────────
  const lenVals = [...new Set(lengths)].sort((a, b) => a - b);
  if (lenVals.length === 0 || lenVals.some(k => !Number.isInteger(k) || k < 2)) {
    throw new Error('extractMetaPaths(): `length` must be one or more integers ≥ 2.');
  }

  // ── Enumerate or search ─────────────────────────────────────────────
  type RawRow = {
    schema: string;
    length: number;
    gap: number;
    count: number;
    nSequences: number;
    expectedP: number;
    totalWindows: number;
  };
  const raw: RawRow[] = [];

  if (schema !== undefined) {
    const partsIdx = parsePattern(schema, alphabet);
    const k = partsIdx.length;
    for (const g of gapVals) {
      const rows = searchPattern(intSeqs, partsIdx, T, g, alphabet, margP);
      for (const r of rows) {
        raw.push({ ...r, length: k, gap: g });
      }
    }
  } else {
    for (const g of gapVals) {
      for (const k of lenVals) {
        const rows = enumeratePaths(intSeqs, T, k, g, alphabet, margP);
        for (const r of rows) {
          raw.push({ ...r, length: k, gap: g });
        }
      }
    }
  }

  if (raw.length === 0) return [];

  // ── Compute support, frequency, lift ────────────────────────────────
  // frequency: grouped by (length, gap) — R's ave(count, length, gap)
  const groupSums = new Map<string, number>();
  for (const r of raw) {
    const key = `${r.length}|${r.gap}`;
    groupSums.set(key, (groupSums.get(key) ?? 0) + r.count);
  }

  const rows: MetaPathRow[] = raw.map(r => {
    const expectedCount = r.expectedP * r.totalWindows;
    const lift = expectedCount > 0 ? r.count / expectedCount : NaN;
    const support = r.nSequences / nSeq;
    const groupSum = groupSums.get(`${r.length}|${r.gap}`) ?? 0;
    const frequency = groupSum > 0 ? r.count / groupSum : 0;
    return {
      schema: r.schema,
      length: r.length,
      gap: r.gap,
      count: r.count,
      nSequences: r.nSequences,
      support,
      frequency,
      lift,
    };
  });

  // ── Filter ──────────────────────────────────────────────────────────
  const filtered = rows.filter(r => {
    if (r.count < minCount) return false;
    if (r.support < minSupport) return false;
    if (minLift > 0 && (Number.isNaN(r.lift) || r.lift < minLift)) return false;
    if (start) {
      const first = r.schema.split('->')[0]!;
      if (!start.includes(first)) return false;
    }
    if (end) {
      const parts = r.schema.split('->');
      const last = parts[parts.length - 1]!;
      if (!end.includes(last)) return false;
    }
    if (contain) {
      const parts = r.schema.split('->');
      for (const c of contain) {
        if (!parts.includes(c)) return false;
      }
    }
    return true;
  });

  // ── Sort: length asc, gap asc, count desc ───────────────────────────
  filtered.sort((a, b) => a.length - b.length || a.gap - b.gap || b.count - a.count);
  return filtered;
}

// ────────────────────────────────────────────────────────────────────
//  Helpers (ports of htna:::internal functions)
// ────────────────────────────────────────────────────────────────────

function uniqueInOrder(arr: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const v of arr) {
    if (!seen.has(v)) {
      seen.add(v);
      out.push(v);
    }
  }
  return out;
}

/** marg_p = tabulate(flat+1, T) / length(flat) — per-type marginal frequency. */
function marginalFreq(intSeqs: Int32Array[], T: number): Float64Array {
  let total = 0;
  const tab = new Float64Array(T);
  for (const s of intSeqs) {
    total += s.length;
    for (let i = 0; i < s.length; i++) {
      const idx = s[i]!;
      tab[idx] = (tab[idx] ?? 0) + 1;
    }
  }
  if (total === 0) {
    for (let i = 0; i < T; i++) tab[i] = 1 / T;
  } else {
    for (let i = 0; i < T; i++) tab[i]! /= total;
  }
  return tab;
}

/** Sum over sequences of max(0, len - span); span = (k-1)*(gap+1). */
function totalWindows(intSeqs: Int32Array[], k: number, gap: number): number {
  const span = (k - 1) * (gap + 1);
  let sum = 0;
  for (const s of intSeqs) sum += Math.max(0, s.length - span);
  return sum;
}

/** Encode windows of length k (with gap) as base-T integers. */
function windowCodes(v: Int32Array, k: number, gap: number, T: number): Int32Array {
  const span = (k - 1) * (gap + 1);
  const nValid = v.length - span;
  if (nValid < 1) return new Int32Array(0);
  const out = new Int32Array(nValid);
  const stride = gap + 1;
  for (let j = 0; j < k; j++) {
    const factor = Math.pow(T, j);
    const startIdx = j * stride;
    for (let i = 0; i < nValid; i++) {
      out[i]! += factor * v[startIdx + i]!;
    }
  }
  return out;
}

/** Decode k-digit base-T codes back to per-position digits. */
function decodeCodes(codes: number[], k: number, T: number): number[][] {
  const digits: number[][] = codes.map(() => new Array<number>(k));
  for (let i = 0; i < codes.length; i++) {
    let rem = codes[i]!;
    for (let j = 0; j < k; j++) {
      digits[i]![j] = rem % T;
      rem = Math.floor(rem / T);
    }
  }
  return digits;
}

/** Parse schema string into per-part allowed alphabet indices ("*" = all). */
function parsePattern(pattern: string, alphabet: string[]): number[][] {
  const cleaned = pattern.replace(/\s+/g, '');
  const parts = cleaned.split('->');
  if (parts.length < 2) {
    throw new Error("extractMetaPaths(): `schema` must have at least two elements separated by '->'.");
  }
  return parts.map(p => {
    if (p === '*') return Array.from({ length: alphabet.length }, (_, i) => i);
    const idx = alphabet.indexOf(p);
    if (idx < 0) {
      throw new Error(
        `extractMetaPaths(): unknown alphabet element in schema: "${p}". Known: ${alphabet.join(', ')}.`,
      );
    }
    return [idx];
  });
}

/** Cartesian product of parts_idx — every concrete pattern matching the schema. */
function cartesian(partsIdx: number[][]): number[][] {
  let out: number[][] = [[]];
  for (const part of partsIdx) {
    const next: number[][] = [];
    for (const prefix of out) {
      for (const v of part) next.push([...prefix, v]);
    }
    out = next;
  }
  return out;
}

interface PartialRow {
  schema: string;
  count: number;
  nSequences: number;
  expectedP: number;
  totalWindows: number;
}

function searchPattern(
  intSeqs: Int32Array[],
  partsIdx: number[][],
  T: number,
  gap: number,
  alphabet: string[],
  margP: Float64Array,
): PartialRow[] {
  const k = partsIdx.length;
  const expanded = cartesian(partsIdx);            // [n_targets][k]
  const targets = expanded.map(digits => digitsToCode(digits, T));

  // Map target-code → index in expanded array for fast lookup
  const targetIdx = new Map<number, number>();
  targets.forEach((c, i) => targetIdx.set(c, i));

  const total = new Int32Array(targets.length);
  const inSeq = new Int32Array(targets.length);

  for (const s of intSeqs) {
    const codes = windowCodes(s, k, gap, T);
    if (codes.length === 0) continue;
    const seenInThisSeq = new Set<number>();
    for (let i = 0; i < codes.length; i++) {
      const idx = targetIdx.get(codes[i]!);
      if (idx === undefined) continue;
      total[idx]!++;
      seenInThisSeq.add(idx);
    }
    for (const idx of seenInThisSeq) inSeq[idx]!++;
  }

  const totalWins = totalWindows(intSeqs, k, gap);
  const rows: PartialRow[] = [];
  for (let i = 0; i < targets.length; i++) {
    if (total[i]! === 0) continue;
    const digits = expanded[i]!;
    let expP = 1;
    for (const d of digits) expP *= margP[d]!;
    rows.push({
      schema: digits.map(d => alphabet[d]!).join('->'),
      count: total[i]!,
      nSequences: inSeq[i]!,
      expectedP: expP,
      totalWindows: totalWins,
    });
  }
  return rows;
}

function enumeratePaths(
  intSeqs: Int32Array[],
  T: number,
  k: number,
  gap: number,
  alphabet: string[],
  margP: Float64Array,
): PartialRow[] {
  const nCodes = Math.pow(T, k);
  const total = new Int32Array(nCodes);
  const inSeq = new Int32Array(nCodes);

  for (const s of intSeqs) {
    const codes = windowCodes(s, k, gap, T);
    if (codes.length === 0) continue;
    const seenInThisSeq = new Set<number>();
    for (let i = 0; i < codes.length; i++) {
      total[codes[i]!]!++;
      seenInThisSeq.add(codes[i]!);
    }
    for (const c of seenInThisSeq) inSeq[c]!++;
  }

  const keptCodes: number[] = [];
  for (let c = 0; c < nCodes; c++) {
    if (total[c]! > 0) keptCodes.push(c);
  }
  if (keptCodes.length === 0) return [];

  const digits = decodeCodes(keptCodes, k, T);
  const totalWins = totalWindows(intSeqs, k, gap);
  return keptCodes.map((c, i) => {
    const d = digits[i]!;
    let expP = 1;
    for (const di of d) expP *= margP[di]!;
    return {
      schema: d.map(di => alphabet[di]!).join('->'),
      count: total[c]!,
      nSequences: inSeq[c]!,
      expectedP: expP,
      totalWindows: totalWins,
    };
  });
}

function digitsToCode(digits: number[], T: number): number {
  let c = 0;
  for (let j = 0; j < digits.length; j++) c += Math.pow(T, j) * digits[j]!;
  return c;
}
