/**
 * htna() — Build a Heterogeneous Transition Network.
 *
 * Port of R `build_htna()` from the `htna` package. Produces a single
 * combined TNA model with the actor partition stored as metadata (the
 * `partition` and `actorLevels` fields on TNA), so every downstream
 * analysis can carry it without structural changes.
 *
 * Two input forms are supported:
 *
 *   1. `htna(data, { nodeGroups })`  - tnaj-native form.
 *      The caller passes a SequenceData where sessions are already
 *      chronologically ordered (e.g. interleaved Human/AI events) and a
 *      nodeGroups lookup tagging each code with its actor group. This
 *      is the common case when the upstream pipeline (Dynalytics, etc.)
 *      has already converted long-format event rows to tnaj sequences.
 *
 *   2. `htnaFromLong(rows, opts)`    - long-format form.
 *      Mirrors R `build_htna()` exactly: a flat array of event rows
 *      with per-event actor tags. Handles disambiguation of colliding
 *      codes across actors via the same prefix-with-actor-label rule
 *      as R (`disambiguate = TRUE`).
 */
import { buildModel } from '../core/model.js';
import type { TNA, SequenceData, BuildModelOptions } from '../core/types.js';

// ─────────────────────────────────────────────────────────────────────
//  Form 1 — tnaj-native: combined SequenceData + node→actor lookup
// ─────────────────────────────────────────────────────────────────────

export interface HtnaOptions extends BuildModelOptions {
  /**
   * Node-to-actor lookup: actor name → array of codes belonging to that actor.
   * Each code must appear in exactly one entry (no cross-actor collisions).
   * Intra-actor duplicates are silently de-duplicated.
   */
  nodeGroups: Record<string, string[]>;

  /**
   * Canonical actor ordering, defaults to `Object.keys(nodeGroups)`.
   * Stored on the TNA as `actorLevels` for consistent renderer behavior
   * (color/shape/layout assignment across the partition).
   */
  actorLevels?: string[];
}

/**
 * Build a Heterogeneous TNA from a single combined SequenceData and a
 * node-to-actor lookup. The lookup determines each node's partition tag.
 * Returns a TNA with `partition` and `actorLevels` populated.
 *
 * @throws if any code in `data` is not assigned to any actor in `nodeGroups`,
 *         or if a code appears in more than one actor's entry.
 *
 * @example
 * htna(sessions, {
 *   nodeGroups: {
 *     Human: ['Specify', 'Request', 'Refine'],
 *     AI:    ['Plan', 'Execute', 'Report'],
 *   },
 * });
 */
export function htna(data: SequenceData | number[][], options: HtnaOptions): TNA {
  const { nodeGroups, actorLevels: actorLevelsOpt, ...buildOpts } = options;

  validateNodeGroups(nodeGroups);

  const actorLevels = actorLevelsOpt ?? Object.keys(nodeGroups);
  for (const a of actorLevels) {
    if (!(a in nodeGroups)) {
      throw new Error(`htna(): actorLevels entry "${a}" not present in nodeGroups.`);
    }
  }

  // Build code → actor lookup (errors on cross-actor collision)
  const codeToActor = buildCodeToActor(nodeGroups, actorLevels);

  // Build the underlying model
  const model = buildModel(data, buildOpts);

  // Tag each node with its actor
  const partition = model.labels.map(label => {
    const actor = codeToActor.get(label);
    if (actor === undefined) {
      throw new Error(
        `htna(): code "${label}" in data is not assigned to any actor in nodeGroups. ` +
          `Add it to nodeGroups or filter it out of the input data.`,
      );
    }
    return actor;
  });

  model.partition = partition;
  model.actorLevels = actorLevels;
  return model;
}

// ─────────────────────────────────────────────────────────────────────
//  Form 2 — long-format: one row per event, faithful to R build_htna()
// ─────────────────────────────────────────────────────────────────────

/** One long-format event row. */
export interface LongRow {
  /** Session identifier (events with the same session form one sequence). */
  session: string | number;
  /** Within-session ordering key (events sort ascending by this). */
  order: number;
  /** The code / action that occurred. */
  code: string;
  /** Optional actor-type tag for this event (overrides nodeGroups lookup). */
  actor?: string;
}

export interface HtnaLongOptions extends BuildModelOptions {
  /**
   * Either supply `actorPerRow` semantics (the `actor` field on each row),
   * OR supply a node-level `nodeGroups` lookup. Mutually exclusive.
   */
  nodeGroups?: Record<string, string[]>;
  actorLevels?: string[];
  /**
   * When true, codes appearing under multiple actor labels are renamed
   * to `"<actor>:<code>"` before the model is built, so they become
   * distinct nodes. Default false (collisions throw).
   *
   * Only applicable when actor tags are per-event (`rows[i].actor` set)
   * — without per-event tags, collisions cannot be safely disambiguated.
   */
  disambiguate?: boolean;
}

/**
 * Build a Heterogeneous TNA from long-format event rows. Mirrors the R
 * `build_htna()` semantics: events are sorted by (session, order), then
 * grouped per session, then handed to `buildModel`.
 *
 * Per-event actor tags (`row.actor`) take precedence over `nodeGroups`.
 */
export function htnaFromLong(rows: LongRow[], options: HtnaLongOptions): TNA {
  if (rows.length === 0) {
    throw new Error('htnaFromLong(): rows is empty.');
  }
  const { nodeGroups, actorLevels: actorLevelsOpt, disambiguate = false, ...buildOpts } = options;

  // Determine per-event actor tags
  const haveRowActor = rows.every(r => typeof r.actor === 'string' && r.actor.length > 0);
  if (!haveRowActor && !nodeGroups) {
    throw new Error(
      'htnaFromLong(): supply either per-row `actor` tags on every row, or a `nodeGroups` lookup.',
    );
  }

  // Build per-event actor vector
  let actorVec: string[];
  if (haveRowActor) {
    actorVec = rows.map(r => r.actor!);
  } else {
    const codeToActor = buildCodeToActor(nodeGroups!, actorLevelsOpt ?? Object.keys(nodeGroups!));
    actorVec = rows.map(r => {
      const a = codeToActor.get(r.code);
      if (a === undefined) {
        throw new Error(
          `htnaFromLong(): code "${r.code}" not present in nodeGroups (row session=${String(r.session)}, order=${r.order}).`,
        );
      }
      return a;
    });
  }

  // Derive actorLevels: explicit option > first-occurrence order in data
  const actorLevels = actorLevelsOpt ?? uniqueInOrder(actorVec);

  // Build per-actor code dictionary; detect collisions
  const codesByActor: Record<string, Set<string>> = {};
  for (const a of actorLevels) codesByActor[a] = new Set();
  for (let i = 0; i < rows.length; i++) {
    const a = actorVec[i]!;
    if (!(a in codesByActor)) {
      throw new Error(
        `htnaFromLong(): actor "${a}" appears in data but is not in actorLevels [${actorLevels.join(', ')}].`,
      );
    }
    codesByActor[a]!.add(rows[i]!.code);
  }

  const overlap = computeOverlap(codesByActor, actorLevels);
  if (overlap.length > 0 && !disambiguate) {
    throw new Error(
      `htnaFromLong(): code(s) appear in more than one actor group: ${overlap.join(', ')}. ` +
        `Pass disambiguate: true to prefix codes with the actor label.`,
    );
  }

  // Optionally rename event codes "actor:code" — matches R disambiguate=TRUE
  let workingCodes: string[];
  if (disambiguate) {
    workingCodes = rows.map((r, i) => `${actorVec[i]}:${r.code}`);
    // Rebuild codesByActor with prefixed names
    for (const a of actorLevels) codesByActor[a] = new Set();
    for (let i = 0; i < rows.length; i++) {
      codesByActor[actorVec[i]!]!.add(workingCodes[i]!);
    }
  } else {
    workingCodes = rows.map(r => r.code);
  }

  // Sort by (session, order) — matches R `combined[order(session, order), ]`
  const sessionKeys = uniqueInOrder(rows.map(r => String(r.session)));
  const sessionIndex = new Map(sessionKeys.map((k, i) => [k, i]));
  const sessions: { order: number; code: string }[][] = sessionKeys.map(() => []);
  for (let i = 0; i < rows.length; i++) {
    const si = sessionIndex.get(String(rows[i]!.session))!;
    sessions[si]!.push({ order: rows[i]!.order, code: workingCodes[i]! });
  }
  for (const s of sessions) s.sort((a, b) => a.order - b.order);

  const data: SequenceData = sessions.map(events => events.map(e => e.code));

  // Build the model on the ordered, optionally-prefixed sequences
  const model = buildModel(data, buildOpts);

  // Map each model label back to its actor
  const labelToActor = new Map<string, string>();
  for (const a of actorLevels) {
    for (const c of codesByActor[a]!) labelToActor.set(c, a);
  }
  const partition = model.labels.map(label => {
    const a = labelToActor.get(label);
    if (a === undefined) {
      throw new Error(`htnaFromLong(): internal error — label "${label}" has no actor mapping.`);
    }
    return a;
  });

  model.partition = partition;
  model.actorLevels = actorLevels;
  return model;
}

// ─────────────────────────────────────────────────────────────────────
//  Helpers
// ─────────────────────────────────────────────────────────────────────

function validateNodeGroups(nodeGroups: Record<string, string[]>): void {
  const actors = Object.keys(nodeGroups);
  if (actors.length < 2) {
    throw new Error('htna(): `nodeGroups` must have at least two actor groups.');
  }
  for (const a of actors) {
    if (!Array.isArray(nodeGroups[a])) {
      throw new Error(`htna(): nodeGroups["${a}"] must be an array of code strings.`);
    }
  }
}

function buildCodeToActor(
  nodeGroups: Record<string, string[]>,
  actorLevels: string[],
): Map<string, string> {
  const codeToActor = new Map<string, string>();
  const collisions = new Set<string>();
  for (const actor of actorLevels) {
    const seen = new Set<string>();
    for (const code of nodeGroups[actor] ?? []) {
      if (seen.has(code)) continue; // intra-actor dedup
      seen.add(code);
      if (codeToActor.has(code) && codeToActor.get(code) !== actor) {
        collisions.add(code);
      } else {
        codeToActor.set(code, actor);
      }
    }
  }
  if (collisions.size > 0) {
    throw new Error(
      `htna(): code(s) appear in more than one actor group in nodeGroups: ${[...collisions].join(', ')}. ` +
        `Use htnaFromLong() with disambiguate=true to allow this.`,
    );
  }
  return codeToActor;
}

function computeOverlap(
  codesByActor: Record<string, Set<string>>,
  actorLevels: string[],
): string[] {
  const counts = new Map<string, number>();
  for (const a of actorLevels) {
    for (const c of codesByActor[a] ?? new Set<string>()) {
      counts.set(c, (counts.get(c) ?? 0) + 1);
    }
  }
  return [...counts.entries()].filter(([, n]) => n > 1).map(([c]) => c);
}

function uniqueInOrder(arr: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const v of arr) {
    if (!seen.has(v)) {
      seen.add(v);
      out.push(v);
    }
  }
  return out;
}
