/**
 * formatPaths — TS equivalent of R `print.htna_paths` from htna 0.1.0.
 *
 * Renders MetaPathRow[] (from extractMetaPaths) as a fixed-width text
 * table whose byte layout matches R's `print(mp, n = 10)` exactly so
 * downstream tooling (CarmNote cells, Dynalytics notebook output, CI
 * log diffs) can compare TS and R sessions line-by-line.
 *
 * Output shape:
 *   <header line>: "Meta-paths (type-level) over N sequences"
 *   <summary>:     "Rows: M | Lengths: 2, 3, 4 | Gaps: 0"
 *   <columns>:     right-aligned, single-space-separated, format-matched
 *   <truncation>:  "... (X more)" if row count > n
 *
 * Column widths follow R's data.frame print: each column width =
 *   max(header_width, max_data_width) + 1
 * with all cells right-aligned. Numeric columns are pre-formatted:
 *   support / frequency → "%.3f"     lift → "%.2f"
 */
import type { MetaPathRow } from './metaPaths.js';

export interface FormatPathsOptions {
  /** Max rows to render. Default 10. */
  n?: number;
  /** Total number of sessions the rows came from (for the header line). */
  nSequences?: number;
  /** Level label for the header. Default 'meta' → "Meta-paths (type-level)". */
  level?: 'meta' | 'state' | 'paths';
}

const HEADERS: Record<NonNullable<FormatPathsOptions['level']>, string> = {
  meta: 'Meta-paths (type-level)',
  state: 'Patterns (state-level)',
  paths: 'Paths',
};

const COL_NAMES = ['schema', 'length', 'gap', 'count', 'n_seq', 'support', 'frequency', 'lift'] as const;

export function formatPaths(rows: MetaPathRow[], options: FormatPathsOptions = {}): string {
  const { n = 10, nSequences, level = 'meta' } = options;
  const lines: string[] = [];

  const nSeqStr = nSequences !== undefined ? String(nSequences) : 'NA';
  lines.push(`${HEADERS[level]} over ${nSeqStr} sequences`);

  if (rows.length === 0) {
    lines.push('(no rows met the filters)');
    return lines.join('\n');
  }

  const uniqLen = [...new Set(rows.map(r => r.length))].sort((a, b) => a - b);
  const uniqGap = [...new Set(rows.map(r => r.gap))].sort((a, b) => a - b);
  lines.push(
    `Rows: ${rows.length} | Lengths: ${uniqLen.join(', ')} | Gaps: ${uniqGap.join(', ')}`,
  );

  const shown = rows.slice(0, n);

  // Build per-cell string matrix (header row + data rows)
  const cells: string[][] = [
    [...COL_NAMES],
    ...shown.map(r => [
      r.schema,
      String(r.length),
      String(r.gap),
      String(r.count),
      String(r.nSequences),
      r.support.toFixed(3),
      r.frequency.toFixed(3),
      Number.isFinite(r.lift) ? r.lift.toFixed(2) : 'NA',
    ]),
  ];

  // Column width = max(header, max_data) + 1  (R's data.frame print convention)
  const nCols = COL_NAMES.length;
  const widths: number[] = new Array(nCols).fill(0);
  for (const row of cells) {
    for (let c = 0; c < nCols; c++) {
      if (row[c]!.length > widths[c]!) widths[c] = row[c]!.length;
    }
  }
  for (let c = 0; c < nCols; c++) widths[c]! += 1;

  // Right-align every cell to its column width; join with no separator
  // (the +1 width already supplies the leading-space separator).
  for (const row of cells) {
    const parts = row.map((cell, c) => cell.padStart(widths[c]!));
    lines.push(parts.join(''));
  }

  if (rows.length > n) {
    lines.push(`... (${rows.length - n} more)`);
  }

  return lines.join('\n');
}
