/**
 * diffNetworks — element-wise diff of two TNA weight matrices.
 *
 * Pure data shaper for "plot the difference between two networks"
 * consumers (Dynalytics, CarmNote, demo). NOT an htna 0.1.0 export —
 * this is a helper we provide because every consumer that does diff
 * rendering needs the same structured input.
 *
 * Contract:
 *   - Both inputs must share the same set of labels (any order).
 *   - Output rows enumerate every (from, to) pair where either A or B
 *     has a non-zero weight (zero-weight cells on both sides are skipped).
 *   - `magnitude` is the signed change `b - a`.
 *   - `kind` classifies each edge: 'added' (only in b), 'removed' (only
 *     in a), 'increased' / 'decreased' (in both, magnitude !=0),
 *     'unchanged' (in both, magnitude == 0).
 *
 * For HTNA inputs both partitions must agree; the result carries the
 * shared partition + actorLevels so renderers can color by actor.
 */
import type { TNA } from '../core/types.js';

export interface NetworkDiffEdge {
  from: string;
  to: string;
  weightA: number;
  weightB: number;
  magnitude: number;  // b - a
  kind: 'added' | 'removed' | 'increased' | 'decreased' | 'unchanged';
}

export interface NetworkDiff {
  labels: string[];                    // shared label set in A's order
  partition?: string[];                // present iff both inputs are HTNA
  actorLevels?: string[];
  edges: NetworkDiffEdge[];
  /** Counts by kind for quick summary stats. */
  counts: Record<NetworkDiffEdge['kind'], number>;
}

export function diffNetworks(a: TNA, b: TNA): NetworkDiff {
  // Validate label sets match (order-insensitive)
  if (a.labels.length !== b.labels.length) {
    throw new Error(
      `diffNetworks(): label-count mismatch — A has ${a.labels.length} labels, B has ${b.labels.length}.`,
    );
  }
  const aLabelSet = new Set(a.labels);
  for (const l of b.labels) {
    if (!aLabelSet.has(l)) {
      throw new Error(`diffNetworks(): label "${l}" in B not present in A.`);
    }
  }

  // Map B's label → its index in B (so we can look up B's weights by A's order)
  const bIdx = new Map(b.labels.map((l, i) => [l, i]));

  // Validate partitions agree if both inputs are HTNA
  let partition: string[] | undefined;
  let actorLevels: string[] | undefined;
  if (a.partition && b.partition) {
    const aPart = new Map(a.labels.map((l, i) => [l, a.partition![i]!]));
    for (let bi = 0; bi < b.labels.length; bi++) {
      const aTag = aPart.get(b.labels[bi]!);
      const bTag = b.partition[bi]!;
      if (aTag !== bTag) {
        throw new Error(
          `diffNetworks(): partition mismatch for "${b.labels[bi]}" — A="${aTag}" vs B="${bTag}".`,
        );
      }
    }
    // Use A's partition in A's label order (canonical)
    partition = [...a.partition];
    actorLevels = a.actorLevels ? [...a.actorLevels] : undefined;
  }

  const n = a.labels.length;
  const edges: NetworkDiffEdge[] = [];
  const counts: Record<NetworkDiffEdge['kind'], number> = {
    added: 0, removed: 0, increased: 0, decreased: 0, unchanged: 0,
  };

  for (let i = 0; i < n; i++) {
    const fromLabel = a.labels[i]!;
    const bi = bIdx.get(fromLabel)!;
    for (let j = 0; j < n; j++) {
      const toLabel = a.labels[j]!;
      const bj = bIdx.get(toLabel)!;
      const wa = a.weights.get(i, j);
      const wb = b.weights.get(bi, bj);
      if (wa === 0 && wb === 0) continue;
      const mag = wb - wa;
      let kind: NetworkDiffEdge['kind'];
      if (wa === 0) kind = 'added';
      else if (wb === 0) kind = 'removed';
      else if (mag > 0) kind = 'increased';
      else if (mag < 0) kind = 'decreased';
      else kind = 'unchanged';
      edges.push({ from: fromLabel, to: toLabel, weightA: wa, weightB: wb, magnitude: mag, kind });
      counts[kind]++;
    }
  }

  return { labels: [...a.labels], partition, actorLevels, edges, counts };
}
